def subtract(a, b):
    def merge_intervals(intervals):
        if not intervals:
            return []

        # Filter out empty intervals and sort
        valid = [iv for iv in intervals if iv[0] < iv[1]]
        if not valid:
            return []

        valid.sort()

        # Merge overlapping/touching intervals
        merged = [valid[0]]
        for start, end in valid[1:]:
            if start <= merged[-1][1]:
                merged[-1][1] = max(merged[-1][1], end)
            else:
                merged.append([start, end])

        return merged

    # Merge intervals in a
    a_merged = merge_intervals(a)
    if not a_merged:
        return []

    # Merge intervals in b
    b_merged = merge_intervals(b)
    if not b_merged:
        return a_merged

    result = []

    for a_start, a_end in a_merged:
        current_ranges = [[a_start, a_end]]

        # Subtract each interval in b from current ranges
        for b_start, b_end in b_merged:
            new_ranges = []
            for r_start, r_end in current_ranges:
                # No overlap
                if r_end <= b_start or r_start >= b_end:
                    new_ranges.append([r_start, r_end])
                else:
                    # There is overlap
                    if r_start < b_start:
                        new_ranges.append([r_start, b_start])
                    if r_end > b_end:
                        new_ranges.append([b_end, r_end])
            current_ranges = new_ranges

        result.extend(current_ranges)

    return result

